fn words(x:QM31)->[u32;4]{[x.c0.a.0,x.c0.b.0,x.c1.a.0,x.c1.b.0]}
#[kani::proof]#[kani::unwind(10)]
#[kani::stub(core::ptr::copy_nonoverlapping,KMX_copy_nonoverlapping)]
fn NHU_lift(){let raw:u32=kani::any();let out=lift_m31(M31(raw));let i:usize=kani::any();kani::assume(i<4);assert_eq!(words(out)[i],(if i==0{raw}else{0})^if cfg!(NHU_invert){1}else{0});}
fn digest()->Digest{let v:[u32;8]=kani::any();core::array::from_fn(|i|M31(v[i]))}
fn transition()->PoolV1PairLatePublicStatementV1{PoolV1PairLatePublicStatementV1{live_snapshot:crate::pool_v1::pair_tree_profile::PoolV1PairLiveSnapshotV1{pool:kani::any(),deployment_domain:kani::any(),sequence:kani::any(),next_pair_index:kani::any(),current_root:digest(),frontier:core::array::from_fn(|_|digest())},candidate_afterstate:crate::pool_v1::PoolV1PairVerifiedAfterstateV1{next_pair_index:kani::any(),next_root:digest(),next_frontier:core::array::from_fn(|_|digest())}}}
fn semantic<'a>(t:&'a PoolV1PairLatePublicStatementV1)->SemanticPublic<'a>{let transfer:bool=kani::any();let recipient:bool=kani::any();let withdrawal:bool=kani::any();SemanticPublic{variant:if transfer{CompiledVariant::PrivateTransfer}else{CompiledVariant::Withdrawal},pool:kani::any(),deployment_domain:kani::any(),anchor:digest(),nullifier:digest(),asset_id:M31(kani::any()),recipient:if recipient{Some(digest())}else{None},change:digest(),withdrawal_amount:if withdrawal{Some(kani::any())}else{None},transition:t}}
struct CarryLog{count:usize,arg:u64,reply:usize}
fn carry_cut(index:u64,log:&mut CarryLog)->usize{log.count+=1;log.arg=index;log.reply}
