#[kani::proof]#[kani::unwind(200)]
#[kani::stub(core::ptr::copy_nonoverlapping,KMX_copy_nonoverlapping)]
fn NHU_transition_header(){let t=transition();let public=semantic(&t);let source=t.live_snapshot;let after=t.candidate_afterstate;let valid=source.pool==public.pool&&source.deployment_domain==public.deployment_domain&&source.sequence==source.next_pair_index&&source.next_pair_index<POOL_V1_PAIR_CAPACITY&&source.next_pair_index.checked_add(1)==Some(after.next_pair_index);let reply:usize=kani::any();kani::assume(reply<=20);let mut log=CarryLog{count:0,arg:0,reply};let out=NHU_transition_header_cut(public,&mut log);assert_eq!(out.is_ok(),valid^cfg!(NHU_invert));if valid{assert_eq!(log.count,1);assert_eq!(log.arg,source.next_pair_index);assert_eq!(out.unwrap(),(source.next_pair_index,reply));}else{assert_eq!(log.count,0);assert!(matches!(out,Err(PoolV1PairForestSemanticTerminalErrorV1::InvalidAppendTransition)));}}
#[kani::proof]#[kani::unwind(200)]
#[kani::stub(core::ptr::copy_nonoverlapping,KMX_copy_nonoverlapping)]
fn NHU_transition_step(){let t=if cfg!(NIH_short){NIH_short_transition()}else{transition()};let public=semantic(&t);let level:usize=kani::any();kani::assume(level<=20);let carry:usize=kani::any();kani::assume(carry<=20);if cfg!(NHU_step_empty){kani::assume(level==20);}if cfg!(NHU_step_skip){kani::assume(level==carry&&carry<20);}if cfg!(NHU_step_fixed){kani::assume(level==0&&carry==20);}if cfg!(NIH_short){kani::assume(carry==2);}if cfg!(NIH_first){kani::assume(level==0&&carry==1);}if cfg!(NIH_earlier){kani::assume(level<carry&&level<20);}if cfg!(NIH_frontier){kani::assume(level<20&&level>carry&&((t.live_snapshot.next_pair_index>>level)&1)==1);}if cfg!(NIH_even){kani::assume(level<20&&level>carry&&((t.live_snapshot.next_pair_index>>level)&1)==0);}if cfg!(NIH_level0){kani::assume(level==0);}if cfg!(NIH_level1){kani::assume(level==1);}if cfg!(NIH_level2){kani::assume(level==2);}if cfg!(NIH_level3){kani::assume(level==3);}if cfg!(NIH_level4){kani::assume(level==4);}if cfg!(NIH_level5){kani::assume(level==5);}if cfg!(NIH_level6){kani::assume(level==6);}if cfg!(NIH_level7){kani::assume(level==7);}if cfg!(NIH_level8){kani::assume(level==8);}if cfg!(NIH_level9){kani::assume(level==9);}if cfg!(NIH_level10){kani::assume(level==10);}if cfg!(NIH_level11){kani::assume(level==11);}if cfg!(NIH_level12){kani::assume(level==12);}if cfg!(NIH_level13){kani::assume(level==13);}if cfg!(NIH_level14){kani::assume(level==14);}if cfg!(NIH_level15){kani::assume(level==15);}if cfg!(NIH_level16){kani::assume(level==16);}if cfg!(NIH_level17){kani::assume(level==17);}if cfg!(NIH_level18){kani::assume(level==18);}if cfg!(NIH_level19){kani::assume(level==19);}if cfg!(NIH_copy_probe){let after=public.transition.candidate_afterstate;let k:usize=kani::any();kani::assume(k<8);assert_eq!(after.next_frontier[level][k],t.candidate_afterstate.next_frontier[level][k]);}if cfg!(NIH_empty_probe){let want=empty_root(level);let known=[141619947u32,1448060902,524379093,1944458907,1832113773,579270723,752346270,1038346536];let k:usize=kani::any();kani::assume(k<8);assert_eq!(want[k].0,known[k]);}let should_reject=if level==20||level==carry&&carry<20{false}else{let expected=if level<carry||((t.live_snapshot.next_pair_index>>level)&1)==0{empty_root(level)}else{t.live_snapshot.frontier[level]};if cfg!(NIH_scalar_ref){let got=&t.candidate_afterstate.next_frontier[level];got[0].0!=expected[0].0||got[1].0!=expected[1].0||got[2].0!=expected[2].0||got[3].0!=expected[3].0||got[4].0!=expected[4].0||got[5].0!=expected[5].0||got[6].0!=expected[6].0||got[7].0!=expected[7].0}else{t.candidate_afterstate.next_frontier[level]!=expected}};let out=NHU_transition_step_cut(public,carry,level);if cfg!(NIH_return_probe){assert!(out.is_ok());}if cfg!(NIH_reject) {assert!(out.is_err()==(should_reject^cfg!(NHU_invert)),"NHU_step_reject");}match out{Ok(next)=>{if cfg!(NIH_next){assert!(next==if level<20{level+1}else{20},"NHU_step_next")}},Err(e)=>{if cfg!(NIH_error){assert!(matches!(e,PoolV1PairForestSemanticTerminalErrorV1::InvalidAppendTransition),"NHU_step_error")}}};}
pub(super) fn NHU_ref_lift(value:M31)->QM31{QM31{c0:CM31{a:value,b:M31(0)},c1:CM31{a:M31(0),b:M31(0)}}}

fn NIH_short_transition()->PoolV1PairLatePublicStatementV1{
 let raw:[u32;8]=kani::any();
 if cfg!(NIH_fixed_witness){kani::assume(raw[0]==141619947);kani::assume(raw[1]==1448060902);kani::assume(raw[2]==524379093);kani::assume(raw[3]==1944458907);kani::assume(raw[4]==1832113773);kani::assume(raw[5]==579270723);kani::assume(raw[6]==752346270);kani::assume(raw[7]==1038346536);}
 let selected=[M31(raw[0]),M31(raw[1]),M31(raw[2]),M31(raw[3]),M31(raw[4]),M31(raw[5]),M31(raw[6]),M31(raw[7])];
 let mut next_frontier=[[M31(0);8];20];next_frontier[1]=selected;
 PoolV1PairLatePublicStatementV1{
  live_snapshot:crate::pool_v1::pair_tree_profile::PoolV1PairLiveSnapshotV1{
   pool:[0;32],deployment_domain:[0;32],sequence:3,next_pair_index:3,
   current_root:[M31(0);8],frontier:[[M31(0);8];20]},
  candidate_afterstate:crate::pool_v1::PoolV1PairVerifiedAfterstateV1{
   next_pair_index:4,next_root:[M31(0);8],next_frontier}}
}
